;------------------------------------------------------------------------------; Scripteur ......: Daniel Lafrance, Québec, canada.; Nom du fichier .: l-c64-joystick.asm; Cernière m.à j. : 20261030-000000 Francisation des commentaires,; Inspiration ....:;------------------------------------------------------------------------------               .include "l-cbm-conv.asm";------------------------------------------------------------------------------; On prend une photo de tous les registres et on les place en mémoire.;------------------------------------------------------------------------------regsphoto      .block               php                  ; Sauve le registre P. stack-> p, pch, pcl               sta   rega           ; Sauve Acc en mémoire.               pla                  ; stack-> pcl, pch               sta   regp           ; Sauve P en mémoire.               stx   regx           ; Sauve X en mémoire.               sty   regy           ; Sauve Y en mémoire.               tsx                  ; Copie S san X.               stx   regs           ; Sauve S en mémoire.               pla                  ; Récupère pcl. stack-> pch                    sta   regpcl         ; Sauve pcl en mémoire.                pla                  ; Récupère pch. stack->                sta   regpch         ; Sauve pch en mémoire.               lda   rega           ; conversion de A en hexadecimal               pha                  ; stack-> a               lda   zpage1               sta   vzp1l               lda   zpage1+1               sta   vzp1h               lda   zpage2               sta   vzp2l               lda   zpage2+1               sta   vzp2h               lda   regpch               pha                  ; stack-> pch               lda   regpcl               pha                  ; stack-> pcl, pch               ldy   regy               ldx   regx               lda   regp               pha                  ; stack-> p, pcl, pch               lda   rega               plp                  ; stack-> pcl, pch               rtsline           =     23             ; Afficher les registre sur la ligne 23coln           =     0              ; ... à partir de la première colonnecolr           =     vblanc         ; ... dans un texte en blanc.showreg                jsr   pushall               lda   rega               jsr   putahex                              pla                  ; stack->                jsr   lsra4bits               jsr   nibtohex               sta   vala               lda   regy           ; conversion de Y en hexadecimal               pha                  ; stack-> a               jsr   nibtohex               sta   valy+1               pla                  ; stack->               jsr   lsra4bits               jsr   nibtohex               sta   valy               lda   regx           ; conversion de X en hexadecimal               pha                  ; stack-> a               jsr   nibtohex               sta   valx+1               pla                  ; stack->               jsr   lsra4bits               jsr   nibtohex               sta   valx               lda   regp           ; conversion de P en hexadecimal               pha                  ; stack-> a               jsr   nibtohex               sta   valp+1               pla                  ; stack->                jsr   lsra4bits               jsr   nibtohex               sta   valp               lda   regs           ; conversion de S en hexadecimal               pha                  ; stack-> a               jsr   nibtohex               sta   vals+1               pla                  ; stack->                jsr   lsra4bits               jsr   nibtohex               sta   vals               lda   regpch         ; conversion de pch en hexadecimal               pha                  ; stack-> a               jsr   nibtohex               sta   valpch+1               pla                  ; stack->                jsr   lsra4bits               jsr   nibtohex               sta   valpch                   lda   regpcl         ; conversion de pcl en hexadecimal               pha                  ; stack-> a               jsr   nibtohex               sta   valpcl+1               pla                  ; stack->                jsr   lsra4bits               jsr   nibtohex               sta   valpcl               lda   zpage1         ; Conversion LSB Zpage1.               pha                  ; stack-> Zpage1L               jsr   nibtohex                       sta   valz1l                pla                  ; stack->               jsr   lsra4bits               jsr   nibtohex               sta   valz1l+1                       lda   zpage1+1       ; Conversion MSB Zpage1.               pha                  ; stack-> Zpage1H               jsr   nibtohex               sta   valz1h                pla               jsr   lsra4bits               jsr   nibtohex               sta   valz1h+1               lda   zpage2               pha               jsr   nibtohex               sta   valz2l                pla               jsr   lsra4bits               jsr   nibtohex               sta   valz2l+1                lda   zpage2+1               pha               jsr   nibtohex               sta   valz2h                pla               jsr   lsra4bits               jsr   nibtohex               sta   valz2h+1               jsr   setinverse     ; On affiche les chaines               sei               ldx   #<srega               ldy   #>srega+1               jsr   putscxy               ldx   #<sregx               ldy   #>sregx+1               jsr   putscxy               ldx   #<sregy               ldy   #>sregy+1               jsr   putscxy               ldx   #<sregp               ldy   #>sregp+1               jsr   putscxy               ldx   #<sregs               ldy   #>sregs+1               jsr   putscxy               ldx   #<sregpc               ldy   #>sregpc+1               jsr   putscxy               ldx   #<sregz1               ldy   #>sregz1+1               jsr   putscxy               ldx   #<sregz2               ldy   #>sregz2+1               jsr   putscxy               cli               jsr   clrinverse               jsr   popall               rtssrega   .byte   colr,coln,line        .text   ' a:$' ;4,24vala    .byte   0,0,0sregx   .byte   colr,coln+6,line        .text   ' x:$' ;4,24valx    .byte   0,0,0sregy   .byte   colr,coln+12,line        .text   ' y:$' ;4,24valy    .byte   0,0,0sregp   .byte   colr,coln+18,line        .text   ' p:$' ;4,24valp    .byte   0,0,0sregs   .byte   colr,coln+24,line        .text   ' s:$' ;4,24vals    .byte   0,0,0sregpc  .byte   colr,coln+30,line        .text   ' pc:$' ;4,24valpch  .byte   0,0valpcl  .byte   0,0,32,0sregz1  .byte   colr,coln+3,line+1        .text   ' zp1:$' ;4,24valz1h  .byte   0,0valz1l  .byte   0,0,32,0sregz2  .byte   colr,coln+15,line+1        .text   ' zp2:$' ;4,24valz2h  .byte   0,0valz2l  .byte   0,0,32,0rega    .byte   0regx    .byte   0regy    .byte   0regp    .byte   0regs    .byte   0regpch  .byte   0regpcl  .byte   0vzp1h   .byte   0vzp1l   .byte   0vzp2h   .byte   0vzp2l   .byte   0               .bend